import { GroupType } from './types';

export const GROUP_TYPES: GroupType[] = [
  GroupType.SOLOIST,
  GroupType.BOY_GROUP,
  GroupType.GIRL_GROUP,
  GroupType.CO_ED_GROUP,
];

export const DEFAULT_CONCEPT_KEYWORDS = "charismatic, trendy, versatile";
export const MIN_MEMBERS = 1;
export const MAX_MEMBERS = 15;

export const GEMINI_MODEL_TEXT = 'gemini-3-flash-preview';

export const SOCIAL_ICON_MAP: { [key: string]: string } = {
  twitter: "fab fa-twitter",
  instagram: "fab fa-instagram",
  youtube: "fab fa-youtube",
};

import React, { useState, useEffect } from 'react';
import type { UserInput } from '../types';
import { GroupType } from '../types';
import { GROUP_TYPES, DEFAULT_CONCEPT_KEYWORDS, MIN_MEMBERS, MAX_MEMBERS } from '../constants';

interface UserInputFormProps {
  onGenerate: (userInput: UserInput) => void;
  onProfileUpload: (file: File) => void;
  isLoading: boolean;
}

export const UserInputForm: React.FC<UserInputFormProps> = ({ onGenerate, onProfileUpload, isLoading }) => {
  const [groupType, setGroupType] = useState<GroupType>(GroupType.GIRL_GROUP);
  const [numMembers, setNumMembers] = useState<number>(4);
  const [conceptKeywords, setConceptKeywords] = useState<string>(DEFAULT_CONCEPT_KEYWORDS);
  const [fileName, setFileName] = useState<string | null>(null);

  useEffect(() => {
    if (groupType === GroupType.SOLOIST) {
      setNumMembers(1);
    } else {
      if (numMembers === 1) {
        setNumMembers(3);
      }
    }
  }, [groupType, numMembers]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFileName(null); 
    onGenerate({
      groupType,
      numMembers: groupType === GroupType.SOLOIST ? 1 : numMembers,
      conceptKeywords
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFileName(file.name);
      onProfileUpload(file);
    } else {
      setFileName(null);
    }
  };

  // Improved styling for inputs to ensure high legibility and soft aesthetic
  const inputClasses = "w-full p-3 bg-white border border-purple-200 rounded-lg shadow-sm text-gray-900 placeholder-gray-400 focus:ring-2 focus:ring-purple-400 focus:border-purple-400 transition duration-150 outline-none";

  return (
    <div className="bg-white p-6 sm:p-8 rounded-xl shadow-2xl space-y-6 max-w-2xl mx-auto border border-purple-200">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div>
          <label
            htmlFor="groupType"
            className="block text-sm font-medium mb-1 text-purple-700"
          >
            Group Type
          </label>
          <select
            id="groupType"
            value={groupType}
            onChange={(e) => setGroupType(e.target.value as GroupType)}
            className={inputClasses}
            aria-label="Select Group Type"
          >
            {GROUP_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
          </select>
        </div>

        {groupType !== GroupType.SOLOIST && (
          <div>
            <label
              htmlFor="numMembers"
              className="block text-sm font-medium mb-1 text-purple-700"
            >
              Number of Members ({MIN_MEMBERS}-{MAX_MEMBERS})
            </label>
            <input
              type="number"
              id="numMembers"
              value={numMembers}
              onChange={(e) => setNumMembers(Math.max(MIN_MEMBERS, Math.min(MAX_MEMBERS, parseInt(e.target.value, 10) || MIN_MEMBERS)))}
              min={MIN_MEMBERS}
              max={MAX_MEMBERS}
              className={inputClasses}
              aria-label="Number of Members"
            />
          </div>
        )}

        <div>
          <label
            htmlFor="conceptKeywords"
            className="block text-sm font-medium mb-1 text-purple-700"
          >
            Concept Keywords (comma-separated) for AI Generation
          </label>
          <input
            type="text"
            id="conceptKeywords"
            value={conceptKeywords}
            onChange={(e) => setConceptKeywords(e.target.value)}
            placeholder="e.g., dreamy, ethereal, powerful"
            className={inputClasses}
            aria-label="Concept Keywords for AI Generation"
          />
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white font-semibold py-3 px-4 rounded-lg shadow-md hover:shadow-lg focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-opacity-50 transition duration-150 ease-in-out disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {isLoading ? 'Processing...' : 'Generate New Profile with AI'}
        </button>
      </form>

      <div className="pt-4 border-t border-gray-200">
        <label
          htmlFor="profileUpload"
          className="block text-sm font-medium mb-2 text-purple-700"
        >
          Or Upload an Existing Profile (PDF file)
        </label>
        <input
          type="file"
          id="profileUpload"
          accept=".pdf"
          onChange={handleFileChange}
          className="w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-purple-50 file:text-purple-700 hover:file:bg-purple-100 disabled:opacity-50 disabled:cursor-not-allowed cursor-pointer"
          aria-label="Upload existing profile PDF file"
          disabled={isLoading}
        />
        {fileName && !isLoading && <p className="text-xs text-gray-500 mt-1 font-medium">Selected file: {fileName}</p>}
      </div>
    </div>
  );
};

