import type { UserInput, GroupProfileData, MemberProfileData, FullProfile, GroupType } from '../types';
import { generateKpopGroupData, generateKpopMembersData } from './geminiService';

function createGroupPrompt(userInput: UserInput): string {
  const { groupType, numMembers, conceptKeywords, generation } = userInput;
  return `
You are a Senior Creative Director at a major K-pop agency (e.g., HYBE, SM, JYP). 
Generate an authentic, professional industry profile for a new ${generation} ${groupType}.
${groupType !== "Soloist" ? `Number of Members: ${numMembers}` : ''}
Primary Concept: "${conceptKeywords}"

Provide a single, valid JSON object:
{
  "groupName": "string (unique, SEO-friendly, professional)",
  "groupNameMeaning": "string (A&R style explanation of the brand identity)",
  "agency": "string (fictional premium agency name)",
  "debutDate": "string (YYYY-MM-DD)",
  "fandomName": "string (meaningful connection to group name)",
  "officialColors": [
    { "name": "string", "hex": "string", "description": "string (max 20 words)" }
  ],
  "conceptDescription": "string (marketing pitch style, mentioning musical genre and visual style)",
  "logoDescription": "string (minimalist, modern branding description)",
  "marketFocus": "string (e.g., 'Global (US/Europe)', 'Mainstream Domestic', 'Niche Experimental')",
  "discography": [
    { "type": "Mini Album" | "Full Album" | "Single", "title": "string", "releaseDate": "string", "titleTrack": "string" }
  ]
}
Ensure dates are logical. ${generation} should influence the naming and concept style.
`;
}

function createMembersPrompt(numMembers: number, groupType: GroupType, conceptDescription: string, debutDate: string, groupName: string): string {
  const memberRoleGuidance = groupType === "Soloist"
    ? `"positions": ["Soloist"]`
    : `"positions": ["string"] (Use authentic roles: Leader, Main/Lead Vocalist, Main/Lead Rapper, Main/Lead Dancer, Visual, Center, Face of the Group, Maknae). Ensure one Center, one Leader, and one Maknae.`;

  return `
You are a Senior Casting Director. Generate ${numMembers} unique member profiles for the ${groupType.toLowerCase()} "${groupName}".
Concept: "${conceptDescription}"
Debut Date: ${debutDate}

Provide a single, valid JSON array. Each object:
{
  "stageName": "string",
  "fullNameKorean": "string (Hangul)",
  "fullNameRomanized": "string",
  "dateOfBirth": "string (YYYY-MM-DD)",
  "placeOfBirth": "string",
  "heightCM": "number",
  "weightKG": "number",
  "bloodType": "string",
  "zodiacSign": "string",
  "mbti": "string (e.g., ENFP, ISTJ)",
  "trainingPeriod": "string (e.g., '3 years', '5 months')",
  "representativeEmoji": "string",
  ${memberRoleGuidance},
  "bio": "string (Highlight training history, personality, or 'star quality')",
  "representativeAnimal": "string",
  "socialMedia": { "twitter": "string", "instagram": "string", "tiktok": "string" },
  "profileImageDescription": "string (professional studio photoshoot description)"
}
Ages should be realistic for a debut (15-23 generally). Variety in MBTI and personalities is key.
`;
}

export const generateFullKpopProfile = async (userInput: UserInput): Promise<FullProfile> => {
  const groupPrompt = createGroupPrompt(userInput);
  const groupData = await generateKpopGroupData<GroupProfileData>(groupPrompt);

  const membersPrompt = createMembersPrompt(
    userInput.groupType === "Soloist" ? 1 : userInput.numMembers,
    userInput.groupType,
    groupData.conceptDescription,
    groupData.debutDate,
    groupData.groupName
  );
  const membersData = await generateKpopMembersData<MemberProfileData[]>(membersPrompt);

  const cleanedMembers = membersData.map(member => ({
    ...member,
    heightCM: Number(member.heightCM) || 165,
    weightKG: Number(member.weightKG) || 50,
    positions: Array.isArray(member.positions) ? member.positions : [String(member.positions)]
  }));

  return {
    ...groupData,
    members: cleanedMembers,
    groupType: userInput.groupType,
    generation: userInput.generation
  };
};

