  "fandomName": "string",
  "officialColors": [{ "name": "string", "hex": "string", "description": "string" }],
  "conceptDescription": "string",
  "logoDescription": "string",
  "marketFocus": "string",
  "discography": [{ "type": "string", "title": "string", "releaseDate": "string", "titleTrack": "string" }],
  "groupType": "Soloist" | "Boy Group" | "Girl Group" | "Co-ed Group",
  "members": [
    {
      "stageName": "string",
      "fullNameKorean": "string",
      "fullNameRomanized": "string",
      "dateOfBirth": "string",
      "placeOfBirth": "string",
      "heightCM": "number",
      "weightKG": "number",
      "bloodType": "string",
      "zodiacSign": "string",
      "mbti": "string",
      "trainingPeriod": "string",
      "representativeEmoji": "string",
      "positions": ["string"],
      "bio": "string",
      "socialMedia": { "twitter": "string", "instagram": "string", "tiktok": "string" },
