const ProfileDetail: React.FC<{ label: string; value?: string | number | string[] }> = ({ label, value }) => {
  if (!value) return null;
  const displayValue = Array.isArray(value) ? value.join(', ') : value;
  return (
    <div className="flex justify-between text-xs py-1 border-b border-gray-100 last:border-0">
      <span className="font-bold text-purple-600 uppercase tracking-tighter">{label}</span>
      <span className="text-gray-700 font-medium">{displayValue}</span>
    </div>
  );
};

