  useEffect(() => {
    if (groupType === GroupType.SOLOIST) {
      setNumMembers(1);
    } else if (numMembers === 1) {
      setNumMembers(5);
    }
  }, [groupType]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onGenerate({
      groupType,
      numMembers: groupType === GroupType.SOLOIST ? 1 : numMembers,
      conceptKeywords: conceptKeywords.trim() || undefined,
      generation
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setFileName(file.name);
      onProfileUpload(file);
    }
  };

  // Border visibility fix: use indigo-200 and focus purple-500 ring for high legibility
  const inputClasses = "w-full p-4 bg-white border-2 border-indigo-100 rounded-xl shadow-sm text-gray-900 placeholder-gray-400 focus:ring-4 focus:ring-purple-200 focus:border-purple-500 transition-all duration-300 outline-none font-medium";

  return (
    <div className="bg-white/90 backdrop-blur-xl p-8 rounded-3xl shadow-2xl space-y-8 max-w-3xl mx-auto border border-white/40">
      <div className="text-center">
        <h3 className="text-lg font-bold text-indigo-900 uppercase tracking-widest">Global A&R Dashboard</h3>
        <p className="text-sm text-indigo-400">Configure the next world-conquering K-Pop act</p>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-indigo-600 px-1">Artist Type</label>
            <select
              value={groupType}
              onChange={(e) => setGroupType(e.target.value as GroupType)}
              className={inputClasses}
            >
              {GROUP_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-indigo-600 px-1">Concept Era</label>
            <select
              value={generation}
              onChange={(e) => setGeneration(e.target.value as KpopGeneration)}
              className={inputClasses}
            >
              {KPOP_GENERATIONS.map(gen => <option key={gen} value={gen}>{gen}</option>)}
            </select>
          </div>
        </div>

        {groupType !== GroupType.SOLOIST && (
          <div className="space-y-2">
            <label className="text-xs font-black uppercase tracking-widest text-indigo-600 px-1">
              Final Lineup Size ({MIN_MEMBERS}-{MAX_MEMBERS} members)
            </label>
            <input
              type="number"
              value={numMembers}
              onChange={(e) => setNumMembers(Math.max(MIN_MEMBERS, Math.min(MAX_MEMBERS, parseInt(e.target.value, 10) || MIN_MEMBERS)))}
              className={inputClasses}
            />
          </div>
        )}

        <div className="space-y-2">
          <div className="flex justify-between items-center px-1">
            <label className="text-xs font-black uppercase tracking-widest text-indigo-600">Keywords</label>
            <span className="text-[10px] font-bold text-indigo-300 uppercase italic">Optional feature</span>
          </div>
          <input
            type="text"
            value={conceptKeywords}
            onChange={(e) => setConceptKeywords(e.target.value)}
            placeholder="AI will ideate if empty (e.g., retro-noir, cyberpunk-kawaii)"
            className={inputClasses}
          />
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-black py-5 px-8 rounded-2xl shadow-[0_10px_20px_-10px_rgba(79,70,229,0.5)] transform hover:-translate-y-1 active:scale-95 transition-all duration-300 disabled:opacity-50 tracking-widest uppercase text-sm"
        >
