function createGroupPrompt(userInput: UserInput): string {
  const { groupType, numMembers, conceptKeywords, generation } = userInput;
  const conceptContext = conceptKeywords 
    ? `The primary theme is "${conceptKeywords}".` 
    : `IDEATE A VIRAL, TRENDY CONCEPT appropriate for a ${generation} act. Be creative and experimental.`;

  return `
You are a Senior Creative Director at a "Big 4" K-pop agency. 
Develop a professional industry profile for a new ${generation} ${groupType}.
${groupType !== "Soloist" ? `Lineup size: ${numMembers} members.` : ''}
${conceptContext}

Provide a single, valid JSON object following this schema:
{
  "groupName": "string (unique, SEO-friendly, stylized correctly like IVE, aespa, or RIIZE)",
  "groupNameMeaning": "string (deep marketing explanation of the brand identity)",
  "agency": "string (fictional premium agency name)",
  "debutDate": "string (YYYY-MM-DD)",
  "fandomName": "string",
  "officialColors": [
    { "name": "string", "hex": "string", "description": "string (max 15 words)" }
  ],
  "conceptDescription": "string (A&R marketing pitch highlighting the musical direction and lore)",
  "logoDescription": "string (branding/visual design summary)",
  "marketFocus": "string (e.g., 'Global English Market', 'Mainstream domestic South Korea', 'Multi-national Focus')",
  "discography": [
    { "type": "Mini Album" | "Full Album" | "Single", "title": "string", "releaseDate": "string", "titleTrack": "string" }
  ]
}
The output MUST be professional. ${generation} groups often have complex storylines or unique "natural" vibes.
`;
}

function createMembersPrompt(numMembers: number, groupType: GroupType, conceptDescription: string, debutDate: string, groupName: string): string {
  const memberRoleGuidance = groupType === "Soloist"
    ? `"positions": ["Soloist"]`
    : `"positions": ["string"] (Use industry terms: Leader, Center, Main/Lead Vocalist, Main/Lead Rapper, Main/Lead Dancer, Visual, Face of the Group, Maknae). One member MUST be the Center. One MUST be the Maknae.`;

  return `
You are an Agency Casting Director. Generate ${numMembers} unique member profiles for the ${groupType.toLowerCase()} "${groupName}".
Concept: "${conceptDescription}"
Debut Date: ${debutDate}

Provide a JSON array where each object is:
{
  "stageName": "string",
  "fullNameKorean": "string (Hangul)",
  "fullNameRomanized": "string",
  "dateOfBirth": "string (YYYY-MM-DD)",
  "placeOfBirth": "string",
  "heightCM": "number",
  "weightKG": "number",
  "bloodType": "string",
  "zodiacSign": "string",
  "mbti": "string (e.g. INFJ, ENFP)",
  "trainingPeriod": "string (e.g. '4 years', '8 months')",
  "representativeEmoji": "string",
  "representativeAnimal": "string",
  ${memberRoleGuidance},
  "stats": {
    "vocal": "number (1-10)",
    "dance": "number (1-10)",
    "rap": "number (1-10)",
    "visual": "number (1-10)"
  },
  "bio": "string (Highlight their 'IT' factor, audition story, or unique charm)",
  "socialMedia": { "twitter": "string", "instagram": "string", "tiktok": "string" },
  "profileImageDescription": "string (detailed photoshoot outfit/vibe description)"
}
Ensure ages and training periods are realistic (debuting between 14 and 24).
`;
}

export const generateFullKpopProfile = async (userInput: UserInput): Promise<FullProfile> => {
  const groupPrompt = createGroupPrompt(userInput);
  const groupData = await generateKpopGroupData<GroupProfileData>(groupPrompt);

  const membersPrompt = createMembersPrompt(
    userInput.groupType === "Soloist" ? 1 : userInput.numMembers,
    userInput.groupType,
    groupData.conceptDescription,
    groupData.debutDate,
    groupData.groupName
  );
  const membersData = await generateKpopMembersData<MemberProfileData[]>(membersPrompt);

  return {
    ...groupData,
    members: membersData.map(m => ({
        ...m,
        heightCM: Number(m.heightCM),
        weightKG: Number(m.weightKG)
    })),
    groupType: userInput.groupType,
    generation: userInput.generation
  };
};

export function createProfileFromPdfTextPrompt(pdfText: string): string {
  const sanitizedPdfText = pdfText.replace(/`/g, '\\`');
  return `
You are a K-Pop Industry Data Parser. Extract the following PDF content into the professional A&R schema.
PDF TEXT:
${sanitizedPdfText}

Output only valid JSON. Ensure all fields (mbti, trainingPeriod, positions, stats) are included even if you have to infer them reasonably based on the artist's history.
`;
}

