import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { GEMINI_MODEL_TEXT, GEMINI_MODEL_IMAGE } from '../constants';
import type { GroundingSource } from '../types';

const API_KEY = process.env.API_KEY;

const getAIInstance = () => {
  if (!API_KEY) {
    throw new Error("Gemini API Key is not configured.");
  }
  return new GoogleGenAI({ apiKey: API_KEY });
};

export async function generateContentWithRetry<T,>(prompt: string, useSearch: boolean = false): Promise<{ data: T, sources?: GroundingSource[] }> {
  const ai = getAIInstance();
  try {
    const config: any = {
      responseMimeType: "application/json",
    };

    if (useSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: GEMINI_MODEL_TEXT,
      contents: prompt,
      config: config,
    });

    let jsonStr = response.text.trim();
    const fenceRegex = /^```(?:json)?\s*\n?(.*?)\n?\s*```$/s;
    const match = jsonStr.match(fenceRegex);
    if (match && match[1]) {
      jsonStr = match[1].trim();
    }

    const data = JSON.parse(jsonStr) as T;

    // Extract sources if search was used
    const sources: GroundingSource[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({
            title: chunk.web.title || 'Market Source',
            uri: chunk.web.uri
          });
        }
      });
    }

    return { data, sources: sources.length > 0 ? sources : undefined };
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw error;
  }
}

export async function generateMemberImage(prompt: string): Promise<string> {
  const ai = getAIInstance();
  const response = await ai.models.generateContent({
    model: GEMINI_MODEL_IMAGE,
    contents: { parts: [{ text: prompt }] },
    config: {
        imageConfig: {
            aspectRatio: "1:1"
        }
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No image data returned from model.");
}

export const generateKpopGroupData = async <T,>(prompt: string): Promise<{ data: T, sources?: GroundingSource[] }> => {
  return generateContentWithRetry<T>(prompt, true);
};

export const generateKpopMembersData = async <T,>(prompt: string): Promise<{ data: T }> => {
  return generateContentWithRetry<T>(prompt, false);
};

