export const generateFullKpopProfile = async (userInput: UserInput): Promise<FullProfile> => {
  const groupPrompt = createGroupPrompt(userInput);
  const { data: groupData, sources } = await generateKpopGroupData<GroupProfileData>(groupPrompt);

  const membersPrompt = createMembersPrompt(
    userInput.groupType === "Soloist" ? 1 : userInput.numMembers,
    userInput.groupType,
    groupData.conceptDescription,
    groupData.groupName
  );
  const { data: membersData } = await generateKpopMembersData<MemberProfileData[]>(membersPrompt);

  return {
    ...groupData,
    sources,
    members: membersData.map(m => ({ ...m, heightCM: Number(m.heightCM), weightKG: Number(m.weightKG) })),
    groupType: userInput.groupType,
    generation: userInput.generation
  };
};

