import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { GEMINI_MODEL_TEXT, GEMINI_MODEL_IMAGE } from '../constants';
import type { GroundingSource } from '../types';

// Per-call instantiation ensures the latest API key is always used
export async function generateContentWithRetry<T,>(prompt: string, useSearch: boolean = false): Promise<{ data: T, sources?: GroundingSource[] }> {
  // Always create a new instance right before making an API call
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const config: any = {
      responseMimeType: "application/json",
    };

    if (useSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: GEMINI_MODEL_TEXT,
      contents: prompt,
      config: config,
    });

    // Access text as a property, not a method
    let jsonStr = response.text.trim();
    const fenceRegex = /^```(?:json)?\s*\n?(.*?)\n?\s*```$/s;
    const match = jsonStr.match(fenceRegex);
    if (match && match[1]) {
      jsonStr = match[1].trim();
    }

    const data = JSON.parse(jsonStr) as T;

    // Extract sources if search was used
    const sources: GroundingSource[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({
            title: chunk.web.title || 'Market Source',
            uri: chunk.web.uri
          });
        }
      });
    }

    return { data, sources: sources.length > 0 ? sources : undefined };
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw error;
  }
}

export async function generateMemberImage(prompt: string): Promise<string> {
  // Always create a new instance right before making an API call
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const response = await ai.models.generateContent({
    model: GEMINI_MODEL_IMAGE,
    contents: { parts: [{ text: prompt }] },
    config: {
        imageConfig: {
            aspectRatio: "1:1"
        }
    }
  });

  // Iterate through parts to find the image part
  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("No image data returned from model.");
}

export const generateKpopGroupData = async <T,>(prompt: string): Promise<{ data: T, sources?: GroundingSource[] }> => {
  return generateContentWithRetry<T>(prompt, true);
};

export const generateKpopMembersData = async <T,>(prompt: string): Promise<{ data: T }> => {
  return generateContentWithRetry<T>(prompt, false);
}

import React, { useState, useCallback, useEffect } from 'react';
import { UserInputForm } from './components/UserInputForm';
import { GroupProfileDisplay } from './components/GroupProfileDisplay';
import { MemberProfileCard } from './components/MemberProfileCard';
import { LoadingSpinner } from './components/LoadingSpinner';
import { SectionHeader } from './components/SectionHeader';
import { generateFullKpopProfile, createProfileFromPdfTextPrompt } from './services/profileDataHelper';
import { generateKpopGroupData } from './services/geminiService'; 
import type { UserInput, FullProfile, MemberProfileData } from './types';
import { GroupType } from './types';

// Declare pdfjsLib globally for TypeScript
declare global {
  interface Window {
    pdfjsLib: any;
  }
}

const App: React.FC = () => {
  const [profile, setProfile] = useState<FullProfile | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [loadingMessage, setLoadingMessage] = useState<string>('Generating K-Pop Magic...');
  const [error, setError] = useState<string | null>(null);
  const [pdfJsWorkerSrcSet, setPdfJsWorkerSrcSet] = useState(false);

  useEffect(() => {
    // Setup pdf.js using the global window.pdfjsLib provided by the CDN script
    async function setupPdfJs() {
      try {
        // Check if pdfjsLib is available on the window object
        if (window.pdfjsLib) {
          // Set the worker source to the CDN path
          window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs';
          setPdfJsWorkerSrcSet(true);
        } else {
          // This might happen if the CDN script in index.html fails to load or execute
          console.warn("pdf.js library (window.pdfjsLib) not found. PDF functionality will be impaired. Ensure CDN script is loaded.");
          setError("PDF processing library failed to initialize. Please check your internet connection or try refreshing the page.");
        }
      } catch (e) {
        console.error("Error setting up pdf.js:", e);
        setError("PDF processing library encountered an unexpected error during setup. Check console for details.");
      }
    }
    setupPdfJs();
  }, []);


  const handleGenerateProfile = useCallback(async (userInput: UserInput) => {
    setIsLoading(true);
    setLoadingMessage('Generating New Profile with AI...');
    setError(null);
    setProfile(null);
    try {
      const numMembers = userInput.groupType === GroupType.SOLOIST ? 1 : userInput.numMembers;
      const fullProfileData = await generateFullKpopProfile({ ...userInput, numMembers });
      setProfile(fullProfileData);
    } catch (err) {
      console.error("Error generating profile:", err);
      setError(err instanceof Error ? `Failed to generate profile: ${err.message}. Check console for details. Ensure API key is set.` : "An unknown error occurred during generation.");
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleProfileFileUpload = useCallback(async (file: File) => {
    if (!pdfJsWorkerSrcSet) {
        setError("PDF processing library is not ready. Please wait a moment or refresh.");
        return;
    }

    const pdfjsLib = window.pdfjsLib; // Use the global pdfjsLib
    if (!pdfjsLib) {
      setError("PDF processing library (window.pdfjsLib) is not available. Cannot process PDF.");
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    setLoadingMessage('Processing PDF File...');
    setError(null);
    setProfile(null);

    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdfDoc = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      let pdfTextContent = "";

      for (let i = 1; i <= pdfDoc.numPages; i++) {
        const page = await pdfDoc.getPage(i);
        const textContent = await page.getTextContent();
        textContent.items.forEach((item: any) => { // item is TextItem
          if (item.str) { // Ensure item.str exists
             pdfTextContent += item.str + " ";
          }
        });
        pdfTextContent += "\n"; // Add a newline after each page's content
      }

      if (pdfTextContent.trim().length === 0) {
        throw new Error("No text content could be extracted from the PDF. The PDF might be image-based or empty.");
      }

      setLoadingMessage('Extracting profile from PDF content using AI...');
      const prompt = createProfileFromPdfTextPrompt(pdfTextContent);
      // Destructure data and sources from the result of generateKpopGroupData to avoid property access errors
      const { data: parsedData, sources } = await generateKpopGroupData<FullProfile>(prompt);

      // Validate parsedData properties instead of the result wrapper
      if (
        !parsedData ||
        typeof parsedData.groupName !== 'string' ||
        typeof parsedData.agency !== 'string' ||
        typeof parsedData.debutDate !== 'string' ||
        typeof parsedData.fandomName !== 'string' ||
        !Array.isArray(parsedData.officialColors) ||
        typeof parsedData.conceptDescription !== 'string' ||
        !Array.isArray(parsedData.members) ||
        !Object.values(GroupType).includes(parsedData.groupType)
      ) {
        throw new Error("AI failed to structure PDF content into the required K-Pop profile format. Please ensure the PDF contains clear profile information that matches the expected fields.");
      }

      if (parsedData.members && parsedData.members.length > 0) {
        const sampleMember = parsedData.members[0];
        if (
            typeof sampleMember.stageName !== 'string' ||
            typeof sampleMember.fullNameKorean !== 'string' ||
            typeof sampleMember.dateOfBirth !== 'string' ||
            !Array.isArray(sampleMember.positions)
        ) {
            throw new Error("AI failed to structure member data correctly from PDF. Please check member details in the PDF or the PDF content itself.");
        }
      }

      // Combine the structured data with extracted grounding intelligence
      const uploadedProfile: FullProfile = { ...parsedData, sources };

      if (uploadedProfile.discography && Array.isArray(uploadedProfile.discography)) {
        uploadedProfile.discography.sort((a, b) => new Date(a.releaseDate).getTime() - new Date(b.releaseDate).getTime());
      }

      if (uploadedProfile.groupType !== GroupType.SOLOIST && uploadedProfile.members.length > 1) {
        uploadedProfile.members.sort((a, b) => new Date(a.dateOfBirth).getTime() - new Date(b.dateOfBirth).getTime());
      }

      setProfile(uploadedProfile);
    } catch (err) {
      console.error("Error processing uploaded PDF profile:", err);
      setError(err instanceof Error ? `Failed to load profile from PDF: ${err.message}. Ensure the PDF contains clear text and the AI can interpret it.` : "An unknown error occurred during PDF file upload processing.");
    } finally {
      setIsLoading(false);
    }
  }, [pdfJsWorkerSrcSet]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-100 via-pink-100 to-indigo-100 text-gray-800 p-4 sm:p-8 font-sans">
      <header className="text-center mb-10">
        <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-purple-600 to-pink-600">
          K-Pop Profile Generator
        </h1>
        <p className="text-gray-600 mt-2 text-lg">Craft your dream K-Pop act or load an existing one!</p>
      </header>

      <UserInputForm 
        onGenerate={handleGenerateProfile} 
        onProfileUpload={handleProfileFileUpload}
        isLoading={isLoading} 
      />

      {isLoading && <LoadingSpinner message={loadingMessage} />}
      {error && <div className="mt-8 p-4 bg-red-100 text-red-700 border border-red-300 rounded-lg text-center whitespace-pre-wrap">{error}</div>}

      {profile && !isLoading && (
        <div className="mt-10 space-y-12">
          <GroupProfileDisplay groupProfile={profile} groupType={profile.groupType} />

          {profile.members && profile.members.length > 0 && (
            <section>
              <SectionHeader title={profile.groupType === GroupType.SOLOIST ? "Soloist Profile" : "Member Profiles"} />
              <div className={`grid grid-cols-1 md:grid-cols-2 ${profile.members.length > 2 ? 'lg:grid-cols-3' : ''} gap-6 mt-6`}>
                {profile.members.map((member, index) => (
                  <MemberProfileCard key={index} member={member} groupColors={profile.officialColors} />
                ))}
              </div>
            </section>
          )}
        </div>
      )}

      <footer className="text-center mt-12 py-6 border-t border-gray-300">
        <p className="text-gray-500 text-sm">
          Generated using AI or loaded from file. Content is fictional unless uploaded by user. Placeholder images from picsum.photos.
        </p>
        <p className="text-xs text-gray-400 mt-1">
          For uploaded PDF profiles, ensure text is clear and structured for best AI interpretation.
        </p>
      </footer>
    </div>
  );
};

