import React, { useState, useCallback, useEffect } from 'react';
import { UserInputForm } from './components/UserInputForm';
import { GroupProfileDisplay } from './components/GroupProfileDisplay';
import { MemberProfileCard } from './components/MemberProfileCard';
import { LoadingSpinner } from './components/LoadingSpinner';
import { SectionHeader } from './components/SectionHeader';
import { generateFullKpopProfile, createProfileFromPdfTextPrompt } from './services/profileDataHelper';
import { generateKpopGroupData } from './services/geminiService'; 
import type { UserInput, FullProfile, MemberProfileData } from './types';
import { GroupType } from './types';

declare global {
  interface Window {
    pdfjsLib: any;
  }
}

const App: React.FC = () => {
  const [profile, setProfile] = useState<FullProfile | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [loadingMessage, setLoadingMessage] = useState<string>('Developing Group Strategy...');
  const [error, setError] = useState<string | null>(null);
  const [pdfJsWorkerSrcSet, setPdfJsWorkerSrcSet] = useState(false);

  useEffect(() => {
    async function setupPdfJs() {
      try {
        if (window.pdfjsLib) {
          window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs';
          setPdfJsWorkerSrcSet(true);
        } else {
          setError("PDF processing library failed to initialize.");
        }
      } catch (e) {
        setError("PDF setup error.");
      }
    }
    setupPdfJs();
  }, []);

  const handleGenerateProfile = useCallback(async (userInput: UserInput) => {
    setIsLoading(true);
    setLoadingMessage('Conducting Market Analysis...');
    setError(null);
    setProfile(null);
    try {
      const numMembers = userInput.groupType === GroupType.SOLOIST ? 1 : userInput.numMembers;
      const fullProfileData = await generateFullKpopProfile({ ...userInput, numMembers });
      setProfile(fullProfileData);
    } catch (err) {
      setError("Failed to generate profile. Please try again.");
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleProfileFileUpload = useCallback(async (file: File) => {
    if (!pdfJsWorkerSrcSet) return;
    const pdfjsLib = window.pdfjsLib;
    if (!pdfjsLib) return;

    setIsLoading(true);
    setLoadingMessage('Ingesting Agency Dossier...');
    setError(null);
    setProfile(null);

    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdfDoc = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      let pdfTextContent = "";
      for (let i = 1; i <= pdfDoc.numPages; i++) {
        const page = await pdfDoc.getPage(i);
        const textContent = await page.getTextContent();
        textContent.items.forEach((item: any) => { if (item.str) pdfTextContent += item.str + " "; });
      }
      const prompt = createProfileFromPdfTextPrompt(pdfTextContent);
      const { data: parsedData, sources } = await generateKpopGroupData<FullProfile>(prompt);
      const uploadedProfile: FullProfile = { ...parsedData, sources };
      setProfile(uploadedProfile);
    } catch (err) {
      setError("PDF extraction failed.");
    } finally {
      setIsLoading(false);
    }
  }, [pdfJsWorkerSrcSet]);

  return (
    <div className="min-h-screen bg-indigo-50 text-gray-900 p-4 sm:p-6 font-sans">
      <header className="text-center mb-6">
        <h1 className="text-3xl font-black text-indigo-950 uppercase tracking-tighter">
          Global A&R Intelligence
        </h1>
        <p className="text-xs text-indigo-400 font-bold uppercase tracking-widest mt-1">K-Pop Profile & Strategy System</p>
      </header>

      <div className="max-w-6xl mx-auto space-y-6">
        <UserInputForm 
          onGenerate={handleGenerateProfile} 
          onProfileUpload={handleProfileFileUpload}
          isLoading={isLoading} 
        />

        {isLoading && <LoadingSpinner message={loadingMessage} />}
        {error && <div className="p-4 bg-red-50 text-red-600 rounded-xl border border-red-100 text-center font-bold text-sm">{error}</div>}

        {profile && !isLoading && (
          <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <GroupProfileDisplay groupProfile={profile} groupType={profile.groupType} />

            {profile.members && profile.members.length > 0 && (
              <section>
                <div className="flex items-center gap-4 mb-4">
                  <div className="h-[2px] flex-grow bg-indigo-100"></div>
                  <h3 className="text-lg font-black text-indigo-950 uppercase tracking-tighter shrink-0">
                    {profile.groupType === GroupType.SOLOIST ? "Individual Dossier" : "Lineup Breakdown"}
                  </h3>
                  <div className="h-[2px] flex-grow bg-indigo-100"></div>
                </div>
                <div className={`grid grid-cols-1 md:grid-cols-2 ${profile.members.length > 2 ? 'lg:grid-cols-3' : ''} gap-4`}>
                  {profile.members.map((member, index) => (
                    <MemberProfileCard key={index} member={member} groupColors={profile.officialColors} />
                  ))}
                </div>
              </section>
            )}
          </div>
        )}
      </div>

      <footer className="text-center mt-10 py-4 border-t border-indigo-100">
        <p className="text-indigo-300 text-[9px] font-bold uppercase tracking-widest">
          A&R Suite v2.0 • Data derived from market analysis
        </p>
      </footer>
    </div>
  );
};

