    members: membersData.map(m => ({ ...m, heightCM: Number(m.heightCM), weightKG: Number(m.weightKG) })),
    groupType: userInput.groupType,
    generation: userInput.generation
  };
};

export function createProfileFromPdfTextPrompt(pdfText: string): string {
  return `Parse PDF into A&R Dossier. No self-referential titles. TEXT: ${pdfText.substring(0, 5000)}`;
}

