import React, { useState, useCallback, useEffect } from 'react';
import { UserInputForm } from './components/UserInputForm';
import { GroupProfileDisplay } from './components/GroupProfileDisplay';
import { MemberProfileCard } from './components/MemberProfileCard';
import { LoadingSpinner } from './components/LoadingSpinner';
import { generateFullKpopProfile, createProfileFromPdfTextPrompt } from './services/profileDataHelper';
import { generateKpopGroupData } from './services/geminiService'; 
import type { UserInput, FullProfile } from './types';
import { GroupType } from './types';

declare global {
  interface Window {
    pdfjsLib: any;
  }
}

type TabType = 'overview' | 'lineup' | 'records';

const App: React.FC = () => {
  const [profile, setProfile] = useState<FullProfile | null>(null);
  const [activeTab, setActiveTab] = useState<TabType>('overview');
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [loadingMessage, setLoadingMessage] = useState<string>('Developing Group Strategy...');
  const [error, setError] = useState<string | null>(null);
  const [pdfJsWorkerSrcSet, setPdfJsWorkerSrcSet] = useState(false);

  useEffect(() => {
    async function setupPdfJs() {
      try {
        if (window.pdfjsLib) {
          window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.worker.min.mjs';
          setPdfJsWorkerSrcSet(true);
        }
      } catch (e) {
        console.error("PDF setup error.");
      }
    }
    setupPdfJs();
  }, []);

  const handleGenerateProfile = useCallback(async (userInput: UserInput) => {
    setIsLoading(true);
    setLoadingMessage('Conducting Market Analysis...');
    setError(null);
    setProfile(null);
    try {
      const numMembers = userInput.groupType === GroupType.SOLOIST ? 1 : userInput.numMembers;
      const fullProfileData = await generateFullKpopProfile({ ...userInput, numMembers });
      setProfile(fullProfileData);
      setActiveTab('overview');
    } catch (err) {
      setError("Strategic generation failed. Please refine your parameters.");
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleProfileFileUpload = useCallback(async (file: File) => {
    if (!pdfJsWorkerSrcSet) return;
    const pdfjsLib = window.pdfjsLib;
    if (!pdfjsLib) return;

    setIsLoading(true);
    setLoadingMessage('Ingesting Agency Dossier...');
    setError(null);
    setProfile(null);

    try {
      const arrayBuffer = await file.arrayBuffer();
      const pdfDoc = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
      let pdfTextContent = "";
      for (let i = 1; i <= pdfDoc.numPages; i++) {
        const page = await pdfDoc.getPage(i);
        const textContent = await page.getTextContent();
        textContent.items.forEach((item: any) => { if (item.str) pdfTextContent += item.str + " "; });
      }
      const prompt = createProfileFromPdfTextPrompt(pdfTextContent);
      const { data: parsedData, sources } = await generateKpopGroupData<FullProfile>(prompt);
      setProfile({ ...parsedData, sources });
      setActiveTab('overview');
    } catch (err) {
      setError("Dossier ingestion failed.");
    } finally {
      setIsLoading(false);
    }
  }, [pdfJsWorkerSrcSet]);

  return (
    <div className="min-h-screen bg-neutral-50 text-neutral-900 p-4 sm:p-6 font-sans selection:bg-indigo-100">
      <header className="max-w-6xl mx-auto mb-8 border-b border-neutral-200 pb-6 flex flex-col md:flex-row justify-between items-center gap-4">
        <div className="text-left">
          <h1 className="text-2xl font-black text-indigo-950 uppercase tracking-tighter">
            A&R Management Suite <span className="text-indigo-500">v3.0</span>
          </h1>
          <p className="text-[10px] text-neutral-400 font-bold uppercase tracking-[0.3em]">Agency Strategic Intelligence & Profile System</p>
        </div>
        {profile && (
          <nav className="flex bg-white rounded-full p-1 shadow-sm border border-neutral-200">
            {(['overview', 'lineup', 'records'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${
                  activeTab === tab 
                    ? 'bg-indigo-600 text-white shadow-md' 
                    : 'text-neutral-400 hover:text-indigo-600'
                }`}
              >
                {tab}
              </button>
            ))}
          </nav>
        )}
      </header>

      <div className="max-w-6xl mx-auto space-y-8">
        {!profile && (
          <UserInputForm 
            onGenerate={handleGenerateProfile} 
            onProfileUpload={handleProfileFileUpload}
            isLoading={isLoading} 
          />
        )}

        {isLoading && <LoadingSpinner message={loadingMessage} />}
        {error && <div className="p-6 bg-red-50 text-red-600 rounded-2xl border border-red-100 text-center font-bold text-sm">{error}</div>}

        {profile && !isLoading && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
            {activeTab === 'overview' && (
              <GroupProfileDisplay groupProfile={profile} groupType={profile.groupType} view="overview" />
            )}

            {activeTab === 'records' && (
              <GroupProfileDisplay groupProfile={profile} groupType={profile.groupType} view="records" />
            )}

            {activeTab === 'lineup' && (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {profile.members.map((member, index) => (
                  <MemberProfileCard key={index} member={member} groupColors={profile.officialColors} />
                ))}
              </div>
            )}

            <div className="mt-12 flex justify-center">
               <button 
                onClick={() => setProfile(null)}
                className="text-[10px] font-black uppercase tracking-widest text-neutral-400 hover:text-indigo-600 border border-neutral-200 px-6 py-3 rounded-full hover:bg-white transition-all"
               >
                 Create New Project
               </button>
            </div>
          </div>
        )}
      </div>

      <footer className="max-w-6xl mx-auto text-center mt-16 py-8 border-t border-neutral-100">
        <p className="text-neutral-300 text-[8px] font-bold uppercase tracking-[0.4em]">
          Restricted Internal Use Only • Property of Global A&R Network
        </p>
      </footer>
    </div>
  );
};

