function createGroupPrompt(userInput: UserInput): string {
  const { groupType, numMembers, conceptKeywords, generation } = userInput;

  const marketBrief = `
A&R STRATEGY BY ERA:
- 2nd Gen: "Theatrical Pop". Bold, high-contrast concepts. Individual "Face of the Group" branding. Hook-heavy choruses.
- 3rd Gen: "Universe Building". Storylines, high-concept music videos, international versatility, R&B/Hip-hop influence.
- 4th Gen: "Performance Tech". Dark/Cyber lore, EDM/Trap experimentalism, TikTok point-choreography, niche lore.
- 5th Gen: "Naturalism & Easy-listening". Lo-fi, House, Jersey Club influences. Y2K/90s nostalgia. Relatable "Best Friend" image.

STRICT BRANDING RULES:
1. NO SELF-REFERENTIAL TITLES: The album and song titles MUST NOT include the group's name or a variation of it. They are separate artistic projects.
2. CONCEPT OVER KEYWORDS: Do not just list keywords. Explain the "Visual Language" (e.g., 'Retro' should specify if it's '80s Disco' or '90s Hip-hop').
3. NO GENERIC AI NAMES: Avoid names like "The Harmony" or "Starry Dreams". Use punchy, alphanumeric, or stylized naming (e.g., IVE, RIIZE, aespa, newjeans).
4. MUSICAL DIRECTION: Define the genre accurately (e.g., 'UK Garage with dream-pop synths').
`;

  return `
You are a Senior A&R Director at a global K-pop label.
Using Google Search to verify current 2024-2025 market trends for ${generation}, produce a professional Group Strategy Dossier.
${marketBrief}
Requested Aesthetic: "${conceptKeywords || 'Cutting-edge innovation'}"

Dossier Output (JSON):
{
  "groupName": "string",
  "groupNameMeaning": "string (Marketing depth)",
  "agency": "string",
  "debutDate": "string (YYYY-MM-DD)",
  "fandomName": "string",
  "officialColors": [{ "name": "string", "hex": "string", "description": "string" }],
  "conceptDescription": "string (Visual language brief)",
  "musicalDirection": "string (Detailed genre/sound profile)",
