import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { GEMINI_MODEL_TEXT } from '../constants';
import type { GroundingSource } from '../types';

// Use gemini-3-pro-image-preview for hyper-realistic results as requested
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

export async function generateContentWithRetry<T,>(prompt: string, useSearch: boolean = false): Promise<{ data: T, sources?: GroundingSource[] }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const config: any = {
      responseMimeType: "application/json",
    };

    if (useSearch) {
      config.tools = [{ googleSearch: {} }];
    }

    const response: GenerateContentResponse = await ai.models.generateContent({
      model: GEMINI_MODEL_TEXT,
      contents: prompt,
      config: config,
    });

    let jsonStr = response.text.trim();

    // Improved JSON extraction for robustness
    if (jsonStr.includes('```')) {
      const match = jsonStr.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (match) jsonStr = match[1].trim();
    }

    const data = JSON.parse(jsonStr) as T;

    const sources: GroundingSource[] = [];
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (groundingChunks) {
      groundingChunks.forEach((chunk: any) => {
        if (chunk.web) {
          sources.push({
            title: chunk.web.title || 'Market Source',
            uri: chunk.web.uri
          });
        }
      });
    }

    return { data, sources: sources.length > 0 ? sources : undefined };
  } catch (error) {
    console.error("AI Generation Error:", error);
    throw error;
  }
}

export async function generateMemberImage(prompt: string): Promise<string> {
  // Check if the user has selected an API key for the high-quality model
  if (window.aistudio) {
    const hasKey = await window.aistudio.hasSelectedApiKey();
    if (!hasKey) {
      await window.aistudio.openSelectKey();
      // Proceed assuming the key was selected successfully to avoid race conditions
    }
  }

  // Create a new instance right before making the call to ensure it uses the most up-to-date key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: [{ text: prompt }] },
      config: {
          imageConfig: {
              aspectRatio: "1:1"
          }
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found.")) {
      // If project not found, trigger key selection again
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  throw new Error("No image data returned from model.");
}

export const generateKpopGroupData = async <T,>(prompt: string): Promise<{ data: T, sources?: GroundingSource[] }> => {
  return generateContentWithRetry<T>(prompt, true);
};

export const generateKpopMembersData = async <T,>(prompt: string): Promise<{ data: T }> => {
  return generateContentWithRetry<T>(prompt, false);
}

