const FORBIDDEN_WORDS = "Project, Horizon, Nexus, Frontier, Vision, Zenith, Pulse, Core, Link, Sync, Protocol, Unit, Alpha, Beta, Genesis, Evolution, Cyber, Matrix, Digital, Neural, Tech, Quantum, Virtual, Bio, Android, Vox, X-7";

function createGroupPrompt(userInput: UserInput): string {
  const { groupType, numMembers, conceptKeywords, generation } = userInput;

  const marketBrief = `
STORYTELLER & BRAND ARCHITECT ROLE:
- Create an ORIGINAL brand. 
- NAME MEANING: Simple and iconic (1 sentence). Like:
  * BLACKPINK: The contrast of being pretty but talented.
  * TWICE: To touch people's hearts twice.
  * STRAY KIDS: Finding your own path outside of expectations.
  * STAYC: Star to a Young Culture.

ORIGINALITY & BRANDING:
- DO NOT use existing group names (e.g., No 'BLACKPINK', 'IVE', 'aespa', 'RIIZE').
- DO NOT use generic AI names like "Project X" or "Horizon". 
- Create punchy, trendy English words or stylized alphanumeric strings.

CONCEPTUAL MANIFESTO:
- NO GENERIC AI BUZZWORDS: Avoid "${FORBIDDEN_WORDS}".
- Keep the narrative cinematic but the core message clear and accessible.
`;

  return `
You are the Executive Creative Director at a Tier-1 K-pop Label.
Using Google Search to verify 2024-2025 market trends for ${generation}, produce a professional A&R Dossier.
${marketBrief}
Keywords: "${conceptKeywords || 'Legendary and Provocative'}"

STRICT JSON OUTPUT FORMAT:
{
  "groupName": "string (A sharp, ORIGINAL non-robotic brand name. DO NOT USE EXISTING NAMES.)",
  "groupNameMeaning": "string (Simple, iconic 1-sentence statement.)",
  "agency": "string",
  "debutDate": "YYYY-MM-DD",
  "fandomName": "string",
  "officialColors": [{ "name": "string", "hex": "#HEXCODE", "description": "string" }],
  "conceptDescription": "string (A cinematic lore manifesto. 2-3 sentences max. No clones of existing groups.)",
  "musicalDirection": "string (Specific sonic identity)",
  "logoDescription": "string",
  "marketFocus": "string",
  "discography": [{ "type": "Mini Album", "title": "string", "releaseDate": "YYYY-MM-DD", "titleTrack": "string" }]
}
`;
}

