export const generateFullKpopProfile = async (userInput: UserInput): Promise<FullProfile> => {
  const groupPrompt = createGroupPrompt(userInput);
  const { data: groupData, sources } = await generateKpopGroupData<GroupProfileData>(groupPrompt);

  const safeGroupData = {
    groupName: groupData.groupName || "ORIGIN_X",
    groupNameMeaning: groupData.groupNameMeaning || "Representing the first step of a new legend.",
    agency: groupData.agency || "Elite Label",
    debutDate: groupData.debutDate || "2025-08-15",
    fandomName: groupData.fandomName || "The Pulse",
    officialColors: groupData.officialColors || [{name: "Onyx", hex: "#121212", description: "Infinite depth"}],
    conceptDescription: groupData.conceptDescription || "A story of self-discovery in a modern world.",
    musicalDirection: groupData.musicalDirection || "Trendy pop with sophisticated production.",
    logoDescription: groupData.logoDescription || "A minimalist emblem.",
    discography: groupData.discography || [],
    marketFocus: groupData.marketFocus || "Global",
  };

  const membersPrompt = createMembersPrompt(
    userInput.groupType === "Soloist" ? 1 : userInput.numMembers,
    userInput.groupType,
    safeGroupData.conceptDescription,
    safeGroupData.groupName
  );
  const { data: membersData } = await generateKpopMembersData<MemberProfileData[]>(membersPrompt);

  const safeMembersData = Array.isArray(membersData) ? membersData : [];

  return {
    ...safeGroupData,
    sources,
    members: safeMembersData.map(m => ({ 
      ...m, 
      heightCM: Number(m.heightCM) || 170, 
      weightKG: Number(m.weightKG) || 55 
    })),
    groupType: userInput.groupType,
    generation: userInput.generation
  };
};

